import gzip
import io
import json
import math
import os
import sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        raw = f.read()
    if raw[:2] == b'\x1f\x8b':
        raw = gzip.decompress(raw)
    return raw.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def local_to_epoch(naive, tz, dst=None):
    """Naive local datetime -> epoch seconds. dst: None (first occurrence) or True/False to pick."""
    cands = []
    for fold in (0, 1):
        d = naive.replace(tzinfo=tz, fold=fold)
        cands.append(d)
    if dst is not None:
        for d in cands:
            if bool(d.dst()) == dst:
                return int((d - EPOCH).total_seconds())
    return int((cands[0] - EPOCH).total_seconds())


def epoch_of(dt):
    return int((dt - EPOCH).total_seconds())


def norm_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'I', 'K', 'CLOCK_IN') else 'OUT'


# ---- format readers: yield (id, emp, dir, epoch) ----

def read_abbr(text, tz):
    header = None
    for row in csv.reader(lines_of(text)):
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row and 'Date' in row:
            header = row
            continue
        if header is None or len(row) < len(header):
            continue
        r = dict(zip(header, row))
        m, d, y = r['Date'].split('/')
        t = r['Time'].upper().split()
        hms = t[0].split(':')
        h, mi, s = int(hms[0]), int(hms[1]), int(hms[2]) if len(hms) > 2 else 0
        if len(t) > 1:
            h = h % 12 + (12 if t[1] == 'PM' else 0)
        naive = datetime(int(y), int(m), int(d), h, mi, s)
        z = r.get('Zone', '').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        yield r['Record'], r['Badge'], norm_dir(r['Punch']), local_to_epoch(naive, tz, dst)


def read_epoch(text, tz):
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and 'heartbeat' not in o:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
            ep = math.floor(ms / 1000)
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            if 'ts_ms' in o:
                ep = math.floor(o['ts_ms'] / 1000)
            else:
                ep = math.floor(o['ts'])
        yield str(pid), emp, norm_dir(d), int(ep)


def read_offset(text, tz):
    rows = csv.reader(lines_of(text), delimiter=';', quotechar='"')
    header = None
    for row in rows:
        if header is None:
            header = [c.strip() for c in row]
            continue
        r = dict(zip(header, row))
        dt = datetime.fromisoformat(r['timestamp'].strip().replace('Z', '+00:00'))
        yield r['punch_id'], r['employee'], norm_dir(r['event']), epoch_of(dt)


def std_offset(tz, epoch):
    d = datetime.fromtimestamp(epoch, tz)
    return d.utcoffset() - (d.dst() or timedelta(0))


def read_legacy(text, tz):
    off = None
    for l in lines_of(text):
        k = l[0]
        if k == 'H':
            tail = l[13:18].strip()
            off = None
            if tail and tail[0] in '+-' and len(tail) >= 5:
                sec = int(tail[1:3]) * 3600 + int(tail[3:5]) * 60
                off = timedelta(seconds=-sec if tail[0] == '-' else sec)
        elif k == 'D':
            l = l.ljust(33)
            pid = l[1:9]
            badge = l[9:15].strip()
            d = 'IN' if l[15] == 'I' else 'OUT'
            ts = l[16:30]
            naive = datetime(int(ts[0:4]), int(ts[4:6]), int(ts[6:8]), int(ts[8:10]), int(ts[10:12]), int(ts[12:14]))
            if off is not None:
                ep = epoch_of(naive.replace(tzinfo=UTC) - off)
            else:
                # standard offset of the site zone, constant all year
                guess = epoch_of(naive.replace(tzinfo=UTC))
                so = std_offset(tz, guess)
                so = std_offset(tz, guess - int(so.total_seconds()))
                ep = epoch_of(naive.replace(tzinfo=UTC) - so)
            yield pid, 'E' + badge, d, ep


