        dd, mm, yy = r['Datum'].split('.')
        t = r['Uhrzeit'].split(':')
        naive = datetime(int(yy), int(mm), int(dd), int(t[0]), int(t[1]), int(t[2]) if len(t) > 2 else 0)
        z = r.get('Zeitzone', '').upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        yield r['Nr'], r['Ausweis'], norm_dir(r['Buchung']), local_to_epoch(naive, tz, dst)


