        if not p:
            continue
        pid = p['id']
        if isinstance(pid, float):
            pid = int(pid)
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        yield str(pid), p['badge'], norm_dir(p['type']), local_to_epoch(naive, tz, None)


