                    ever.add(key)
                    if key not in punches:
                        punches[key] = [emp.strip(), dr, ep]

    # 2. corrections
    corr = []
    cdir = os.path.join(indir, 'corrections')
    if os.path.isdir(cdir):
        for dp, _, fns in os.walk(cdir):
            for fn in sorted(fns):
                text = read_text(os.path.join(dp, fn))
                for r in csv.DictReader(io.StringIO('\n'.join(lines_of(text)))):
                    r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                    corr.append(r)
    corr = [c for c in corr if datetime.fromisoformat(c['issued_at'].replace('Z', '+00:00')) <= cutoff]
    corr.sort(key=lambda c: (datetime.fromisoformat(c['issued_at'].replace('Z', '+00:00')), c['correction_id']))
    applied = 0
    for c in corr:
        key = (c['site'], c['punch_id'])
        act = c['action'].lower()
        if act == 'void':
            if key in punches:
                del punches[key]
                applied += 1
        elif act == 'set':
            if key in punches:
                punches[key][2] = epoch_of(datetime.fromisoformat(c['time'].replace('Z', '+00:00')))
                applied += 1
        elif act == 'add':
            if key not in ever:
                ever.add(key)
                punches[key] = [c['employee'], norm_dir(c['type']), epoch_of(datetime.fromisoformat(c['time'].replace('Z', '+00:00')))]
                applied += 1

    empset = set(emp_ids)
    by_emp = {}
    for (site, pid), (emp, dr, ep) in punches.items():
        if emp in empset:
            by_emp.setdefault(emp, []).append((ep, 0 if dr == 'OUT' else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emp_ids}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def rnd(site, ep):
        tz = zones[site]
        off = int(datetime.fromtimestamp(ep, tz).utcoffset().total_seconds())
        s = ep + off
        r = ((s + 180) // 360) * 360
        return ep + (r - s)

    def workday(emp, rep):
        return datetime.fromtimestamp(rep, home_zone[emp]).date()

    def inp(d):
        return pstart <= d <= pend

    def night_minutes(site, a, b):
        tz = zones[site]
        oa = datetime.fromtimestamp(a, tz).utcoffset()
        ob = datetime.fromtimestamp(b, tz).utcoffset()
        n = 0
        if oa == ob:
            o = int(oa.total_seconds())
            m = (a + o) // 60
            end = (b + o) // 60
            for x in range(m, end):
                h = (x % 1440) // 60
                if h >= 22 or h < 6:
                    n += 1
        else:
            for t in range(a, b, 60):
                h = datetime.fromtimestamp(t, tz).hour
                if h >= 22 or h < 6:
                    n += 1
        return n

    for emp, lst in by_emp.items():
        lst.sort(key=lambda p: (p[0], p[1], p[2], p[3]))
        kept = []
        last = None
        for ep, _, site, pid, dr in lst:
            rep = rnd(site, ep)
            if last is not None and last[4] == dr and ep - last[0] <= 300:
                if inp(workday(emp, rep)):
                    exc['duplicates_dropped'] += 1
                continue
            p = (ep, 0, site, pid, dr, rep)
            kept.append(p)
            last = p
        shifts = []
        i = 0
        n = len(kept)
        while i < n:
            p = kept[i]
            if p[4] == 'IN':
                if i + 1 < n and kept[i + 1][4] == 'OUT' and kept[i + 1][5] - p[5] <= 16 * 3600:
                    shifts.append((p, kept[i + 1]))
                    i += 2
                    continue
                if inp(workday(emp, p[5])):
                    exc['open_shifts'] += 1
            else:
                if inp(workday(emp, p[5])):
                    exc['orphan_outs'] += 1
            i += 1
        # shifts in period
        items = []
        for pi, po in shifts:
            wd = workday(emp, pi[5])
            if not inp(wd):
                continue
            worked = max(0, (po[5] - pi[5]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(pi[2], pi[5], po[5]), paid)
            items.append((pi[5], wd, paid, night))
        items.sort(key=lambda x: x[0])
        daily = {}
        weekly = {}
        r = res[emp]
        for rin, wd, paid, night in items:
            done = daily.get(wd, 0)
            reg_day = max(0, min(paid, 480 - done))
            dot = paid - reg_day
            daily[wd] = done + paid
            wk = wd - timedelta(days=wd.weekday())
            wdone = weekly.get(wk, 0)
            wreg = max(0, min(reg_day, 2400 - wdone))
            wot = reg_day - wreg
            weekly[wk] = wdone + reg_day
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for eff, rt in rates.get(emp, []):
                if eff <= wd:
                    rate = rt
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
            r['gross'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    out_emp = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tot_c = 0
    for e in emp_ids:
        r = res[e]
        c = money(r['gross'])
        out_emp[e] = dict(shifts=r['shifts'], paid_minutes=r['paid_minutes'], overtime_minutes=r['overtime_minutes'],
                          night_minutes=r['night_minutes'], gross=fmt_cents(c))
        for k in tot:
            tot[k] += r[k]
        tot_c += c
    tot['gross'] = fmt_cents(tot_c)
    with open(outfile, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']}, 'employees': out_emp,
                   'exceptions': exc, 'totals': tot}, f, indent=1)


